-- Descripciones mejoradas para las 18 experiencias de turismo comunitario

-- 1. Reserva de la Biosfera Sierra Gorda (id=1)
UPDATE experiences SET 
description = 'Adéntrate en una de las reservas de biosfera más biodiversas de México, hogar de más de 2,300 especies de plantas y 800 especies de fauna. La comunidad local te guiará por senderos ancestrales a través de bosques de niebla, selvas medianas y matorrales desérticos. Participa en talleres de conservación, observa el quetzal en su hábitat natural y disfruta de la gastronomía serrana elaborada con ingredientes orgánicos cultivados por las familias locales. Una experiencia que combina aventura, aprendizaje y el compromiso genuino de las comunidades con la protección de su patrimonio natural.',
shortDescription = 'Explora la biodiversidad única de la Sierra Gorda con guías comunitarios expertos en conservación y tradiciones serranas.'
WHERE id = 1;

-- 2. Reserva Sian Ka'an (id=2)
UPDATE experiences SET 
description = 'Navega por los canales ancestrales mayas en la Reserva de la Biosfera Sian Ka''an, Patrimonio de la Humanidad por la UNESCO. Los pescadores locales de la comunidad maya te llevarán en lanchas tradicionales a través de manglares donde habitan manatíes, cocodrilos y más de 300 especies de aves. Descubre cenotes ocultos, ruinas arqueológicas en medio de la selva y playas vírgenes del Caribe. Incluye almuerzo con pescado fresco preparado al estilo tradicional maya y la oportunidad de aprender técnicas ancestrales de pesca sostenible.',
shortDescription = 'Navega los canales mayas de Sian Ka''an con pescadores locales y descubre la magia del Caribe mexicano.'
WHERE id = 2;

-- 3. Cascadas de Agua Azul (id=3)
UPDATE experiences SET 
description = 'Maravíllate con el espectáculo natural de las cascadas de agua turquesa que descienden en más de 500 escalones de roca caliza. La comunidad tzeltal de Agua Azul te recibirá con su hospitalidad tradicional, guiándote por senderos seguros hasta miradores exclusivos. Báñate en las pozas cristalinas, aprende sobre las plantas medicinales de la selva chiapaneca y degusta platillos tradicionales como el cochito horneado y tamales de chipilín. Los guías locales compartirán historias y leyendas mayas mientras exploras este paraíso natural.',
shortDescription = 'Descubre las impresionantes cascadas turquesas de Chiapas con la comunidad tzeltal como anfitriona.'
WHERE id = 3;

-- 4. Barrancas del Cobre Tarahumara (id=4)
UPDATE experiences SET 
description = 'Vive una aventura épica en las Barrancas del Cobre, un sistema de cañones cuatro veces más grande que el Gran Cañón. Los rarámuri (tarahumaras), corredores legendarios de las montañas, te guiarán por senderos milenarios hasta comunidades remotas donde el tiempo parece detenerse. Duerme en cabañas tradicionales, participa en ceremonias ancestrales, aprende el arte del tejido de canastas y corre junto a los mejores ultramaratonistas del mundo. Incluye viaje en el espectacular tren Chepe Express con vistas panorámicas incomparables.',
shortDescription = 'Explora las majestuosas Barrancas del Cobre con los legendarios corredores rarámuri como guías.'
WHERE id = 4;

-- 5. Selva Lacandona Expedition (id=5)
UPDATE experiences SET 
description = 'Embárcate en una expedición a la última gran selva tropical de Norteamérica con los lacandones, guardianes ancestrales de este ecosistema. Navega ríos cristalinos hasta cascadas escondidas, observa monos aulladores, tucanes y jaguares en su hábitat natural. Pernocta en la comunidad de Lacanjá Chansayab, participa en rituales de agradecimiento a la naturaleza y aprende sobre plantas sagradas utilizadas por los antiguos mayas. Los guías lacandones compartirán conocimientos transmitidos por generaciones sobre la selva y sus secretos.',
shortDescription = 'Adéntrate en la Selva Lacandona con los guardianes ancestrales de la última gran selva de Norteamérica.'
WHERE id = 5;

-- 6. Cenotes Sagrados de Yucatán (id=6)
UPDATE experiences SET 
description = 'Sumérgete en las aguas cristalinas de los cenotes sagrados, portales al inframundo maya. Guías de la comunidad maya local te llevarán a cenotes poco conocidos, lejos de las multitudes turísticas, donde podrás nadar en cavernas iluminadas por rayos de luz celestial. Aprende sobre la importancia espiritual de estos lugares para la cultura maya, participa en una ceremonia de purificación y degusta la cochinita pibil preparada en horno de tierra. Incluye visita a una comunidad apícola maya y degustación de miel melipona.',
shortDescription = 'Descubre cenotes sagrados ocultos con guías mayas y vive ceremonias ancestrales de purificación.'
WHERE id = 6;

-- 7. Santuario de la Mariposa Monarca (id=18)
UPDATE experiences SET 
description = 'Presencia uno de los fenómenos naturales más impresionantes del planeta: la llegada de millones de mariposas monarca que viajan más de 4,000 kilómetros desde Canadá. Los guías purépechas del Ejido El Rosario te conducirán por senderos del bosque de oyamel hasta los santuarios donde millones de mariposas cubren los árboles en un espectáculo de color naranja y negro. Aprende sobre el ciclo migratorio, los esfuerzos de conservación comunitaria y disfruta de la gastronomía michoacana incluyendo corundas y atole de grano. Disponible de noviembre a marzo.',
shortDescription = 'Contempla millones de mariposas monarca con guías purépechas en los bosques sagrados de Michoacán.'
WHERE id = 18;

-- 8. Islas Marietas Nayarit (id=8)
UPDATE experiences SET 
description = 'Navega hacia las Islas Marietas, un archipiélago volcánico protegido donde se encuentra la famosa Playa del Amor, accesible solo nadando a través de un túnel natural. Los pescadores de la cooperativa local te llevarán en lanchas tradicionales para hacer snorkel entre mantarrayas, tortugas marinas y cardúmenes de peces tropicales. Observa colonias de pájaros bobos de patas azules y fragatas. Incluye almuerzo de mariscos frescos en la playa y la oportunidad de aprender sobre las técnicas de pesca sostenible que practican las comunidades costeras.',
shortDescription = 'Explora las paradisíacas Islas Marietas con pescadores locales y descubre la Playa del Amor.'
WHERE id = 8;

-- 9. Hierve el Agua Zapoteca (id=9)
UPDATE experiences SET 
description = 'Contempla las cascadas petrificadas de Hierve el Agua, formaciones geológicas únicas creadas durante miles de años por aguas minerales. La comunidad zapoteca de San Lorenzo Albarradas te recibirá con su hospitalidad tradicional, guiándote por senderos hasta miradores con vistas espectaculares del Valle de Oaxaca. Báñate en las pozas naturales de aguas termales, aprende sobre el sistema de riego prehispánico y degusta tlayudas, tasajo y mezcal artesanal. Los guías locales compartirán la historia y tradiciones de la cultura zapoteca.',
shortDescription = 'Admira las cascadas petrificadas y báñate en pozas termales con la comunidad zapoteca de Oaxaca.'
WHERE id = 9;

-- 10. Ruta del Mezcal Zapoteco (id=10)
UPDATE experiences SET 
description = 'Recorre los palenques tradicionales donde maestros mezcaleros zapotecos destilan el espíritu de Oaxaca utilizando técnicas ancestrales transmitidas por generaciones. Visita campos de agave silvestre, aprende a identificar las diferentes variedades (espadín, tobalá, madrecuixe) y participa en todo el proceso: desde la jima hasta la destilación en ollas de barro. Degusta mezcales artesanales maridados con chapulines, quesillo y chocolate oaxaqueño. Incluye visita al árbol del Tule, el árbol más ancho del mundo, y al sitio arqueológico de Mitla.',
shortDescription = 'Descubre los secretos del mezcal artesanal con maestros mezcaleros zapotecos en Oaxaca.'
WHERE id = 10;

-- 11. Ruta del Mezcal Artesanal (id=11)
UPDATE experiences SET 
description = 'Sumérgete en la cultura del mezcal visitando pequeños palenques familiares en los Valles Centrales de Oaxaca. Cada familia mezcalera tiene su propia receta y tradición, creando destilados únicos que reflejan el terroir y la personalidad del maestro mezcalero. Aprende sobre la sustentabilidad del agave, las diferencias entre mezcal industrial y artesanal, y por qué el mezcal es considerado una bebida sagrada. Incluye comida tradicional oaxaqueña, visita a talleres de alebrijes y textiles, y la oportunidad de crear tu propia botella personalizada.',
shortDescription = 'Visita palenques familiares y aprende el arte ancestral del mezcal con maestros oaxaqueños.'
WHERE id = 11;

-- 12. Avistamiento de Ballenas en Baja (id=12)
UPDATE experiences SET 
description = 'Vive el encuentro más cercano con las ballenas grises en las lagunas de Baja California Sur, el único lugar del mundo donde estos gentiles gigantes se acercan voluntariamente a las embarcaciones para ser acariciados. Los pescadores locales de la Laguna San Ignacio te llevarán en pangas tradicionales para observar madres con sus crías, saltos espectaculares y el característico soplo de estas ballenas que migran desde Alaska. Incluye hospedaje en campamentos ecológicos, avistamiento de lobos marinos y cenas de mariscos bajo las estrellas del desierto.',
shortDescription = 'Acaricia ballenas grises con pescadores locales en las lagunas vírgenes de Baja California Sur.'
WHERE id = 12;

-- 13. Artesanías Textiles de Oaxaca (id=13)
UPDATE experiences SET 
description = 'Aprende el arte milenario del tejido en telar de cintura con maestras artesanas zapotecas de Teotitlán del Valle. Descubre cómo se obtienen los tintes naturales de la grana cochinilla, el añil y el pericón, y crea tu propia pieza textil siguiendo patrones geométricos prehispánicos. Visita talleres familiares donde cada tapete cuenta una historia, conoce el proceso completo desde el hilado de la lana hasta el tejido final. Incluye almuerzo tradicional preparado en comal de barro y visita al mercado de artesanías de Tlacolula.',
shortDescription = 'Teje en telar de cintura con maestras zapotecas y crea tu propia pieza textil tradicional.'
WHERE id = 13;

-- 14. Turismo Rural en la Huasteca (id=14)
UPDATE experiences SET 
description = 'Descubre la magia de la Huasteca Potosina con las comunidades teenek y náhuatl que habitan esta región de cascadas turquesas, pozas cristalinas y selva exuberante. Visita el Sótano de las Golondrinas, una de las cuevas verticales más profundas del mundo, navega por el río Tampaón hasta la cascada de Tamul y explora el surrealista jardín escultórico de Edward James en Xilitla. Los guías locales te enseñarán sobre plantas medicinales, danzas tradicionales y la elaboración del zacahuil, el tamal más grande de México.',
shortDescription = 'Explora cascadas y pozas turquesas de la Huasteca con comunidades teenek y náhuatl.'
WHERE id = 14;

-- 15. Observación de Aves en Yucatán (id=15)
UPDATE experiences SET 
description = 'Acompaña a guías ornitólogos de la comunidad maya en una expedición para observar las más de 500 especies de aves que habitan la Península de Yucatán. Desde el amanecer, recorre manglares, selvas y humedales en busca del flamenco rosado, el tucán pico de canoa, el momoto corona azul y especies endémicas como el colibrí tijereta mexicano. Visita la Reserva de Celestún, hogar de la mayor colonia de flamencos de Norteamérica, y aprende sobre los esfuerzos comunitarios de conservación de hábitats críticos para aves migratorias.',
shortDescription = 'Observa flamencos rosados y aves endémicas con guías ornitólogos mayas en Yucatán.'
WHERE id = 15;

-- 16. Kayak en Manglares de Sian Kaan (id=16)
UPDATE experiences SET 
description = 'Rema en kayak por los canales de manglar de la Reserva de Sian Ka''an, explorando ecosistemas donde conviven manatíes, cocodrilos, delfines y cientos de especies de aves. Los guías de la comunidad maya de Punta Allen te enseñarán técnicas de navegación tradicional y te llevarán a lugares secretos donde podrás flotar en el canal de los antiguos mayas, alimentado por manantiales subterráneos. Incluye snorkel en arrecifes de coral, avistamiento de tortugas marinas y almuerzo de langosta fresca preparada por pescadores locales.',
shortDescription = 'Navega en kayak por manglares vírgenes con guías mayas y descubre la vida marina de Sian Ka''an.'
WHERE id = 16;

-- 17. Ecoturismo Lacandón (id=17)
UPDATE experiences SET 
description = 'Convive con la comunidad lacandona en el corazón de la Selva Lacandona, una de las últimas etnias que mantienen vivas las tradiciones mayas ancestrales. Hospédate en cabañas ecológicas junto al río Lacanjá, participa en caminatas nocturnas para observar fauna silvestre, visita las ruinas de Bonampak con sus murales mayas mejor conservados y navega hasta las cascadas de agua turquesa. Los ancianos lacandones compartirán historias de sus ancestros, conocimientos sobre plantas medicinales y rituales de conexión con la naturaleza.',
shortDescription = 'Vive con los lacandones en la selva y descubre tradiciones mayas ancestrales aún vivas.'
WHERE id = 17;

-- 18. Senderismo en la Sierra Gorda (id=7)
UPDATE experiences SET 
description = 'Recorre los senderos de la Sierra Gorda queretana con guías comunitarios que conocen cada rincón de estas montañas. Atraviesa bosques de niebla donde habitan jaguares y osos negros, descubre cascadas escondidas y visita las cinco misiones franciscanas declaradas Patrimonio de la Humanidad. Pernocta en posadas comunitarias, degusta la gastronomía serrana (gorditas de migajas, enchiladas serranas) y participa en proyectos de reforestación y conservación. Una experiencia que combina aventura, cultura y compromiso ambiental.',
shortDescription = 'Camina por bosques de niebla y visita misiones patrimonio mundial con guías serranos de Querétaro.'
WHERE id = 7;
